import unittest
import relay_payload as app

class Behavior(unittest.TestCase):
    def test_embedded_prefix(self):
        self.assertEqual(app.message_payload('message=cache message=ok'), 'cache message=ok')
        self.assertEqual(app.message_payload('message=message=message='), 'message=message=')
        self.assertEqual(app.message_payload('message= a=b  '), ' a=b  ')
    def test_empty_plain_and_invalid(self):
        self.assertEqual(app.message_payload('message='), '')
        self.assertEqual(app.message_payload('message=ready'), 'ready')
        for line in ['', 'ready', 'xmessage=ready', ' message=ready', 'Message=ready']:
            with self.subTest(line=line), self.assertRaises(ValueError):
                app.message_payload(line)

if __name__ == '__main__':
    unittest.main()

